\label{lem:map}
The following statements are valid.
\begin{enumerate}
    \item For each $\mathtt{c}\in\mathsf{C}$, $\smap{\mathtt{c}}{}$ and $\tmap{\mathtt{c}}{}$ are consistent.
    \item For each $\mathsf{t}\in\mathsf{T}$, $\smap{\mathsf{t}}{}$ and $\mathsf{t}$ are consistent.
    \item For $\mathtt{op}\in\mathsf{O}$, $\,\widetilde{v}\in\mathrm{dom}(\smap{\mathtt{op}}{})$ and $\;\widetilde{\mathsf{t}}\in\mathrm{dom}(\tmap{\mathtt{op}}{})$, if $\,\widetilde{v}\,$ are consistent with $\widetilde{\mathsf{t}}$, then $\smap{\mathtt{op}}{}(\,\widetilde{v}\,)$ are consistent with $\tmap{\mathtt{op}}{}(\,\widetilde{\mathsf{t}}\,)$.
\end{enumerate}

Suppose $(\Gamma,\Sigma)$ is a consistent pair and $\ell$ is a loop indicator.
\begin{enumerate}
    \item For each expression $\mathsf{e}$, if $\typing{\Gamma}{\ell}{\mathsf{e}}{\mathsf{t}}$ for some $\mathsf{t}$, there exists a unique value $v\in\mathbb{V}$ such that $\semantics{\Sigma}{\mathsf{e}}{v}$ and $v$ is consistent with $\mathsf{t}$.
    \item For each statement $\mathsf{s}$, if $\typing{\Gamma}{\ell}{\mathsf{s}}{\Gamma'}$ for some $\Gamma'$, then $\Gamma\subseteq\Gamma'$ and there exists a unique store $\Sigma'$ consistent with $\Gamma'$ such that $\semantics{\Sigma}{\mathsf{s}}{\Sigma'}$.
\end{enumerate}
\label{lem:preservation}

\label{prop:invariant}
Given a statement $\mathsf{s}$ and a consistent pair $(\Sigma,\Gamma)$, if there exists $\Gamma'$ such that $\typing{\Gamma}{\texttt{\#}\mathtt{t}}{\mathsf{s}}{\Gamma'}$, then
\begin{enumerate}
    \item $\domi{\Gamma'}=\domi{\Gamma}$, and
    \item there exists $\Sigma'$ such that $\semantics{\Sigma}{\mathsf{s}}{\Sigma'}$ and $\restr{\Sigma'}{\Gamma'}\sim\restr{\Sigma'}{\Gamma}\sim\restr{\Sigma}{\Gamma}$.
\end{enumerate}
These two conclusions above correspond respectively to i) no new iterable variables are declared, and ii) no existing iterable variables have their values changed.

