\label{lem:time-size}
Let $T(n)\ge n$ be a time function.
The following three are equivalent:
\begin{enumerate}
    \item All CorePolyC programs have an instruction count of $O(T(n))$.
    \item All CorePolyC programs only produce outputs of size $O(T(n))$.
    \item All CorePolyC programs only generate values of size $O(T(n))$.
\end{enumerate}

\label{lem:expr-size}

Given an expression $\mathsf{e}$ and a consistent pair $(\Gamma,\Sigma)$, if there exist $v$ and $\mathsf{t}$ such that $\semantics{\Sigma}{\mathsf{e}}{v}$ and $\typing{\Gamma}{\texttt{\#}\mathtt{f}}{\mathsf{e}}{\mathsf{t}}$, then the following statements hold.
\begin{enumerate}
    \item $\size{v}\le\size{\Sigma}+k$, where $k$ is a constant.
    \item\label{lem:expr-size:2} If $\mathsf{e}$ is iterable, i.e., $\mathsf{t}=\mathtt{iint}$, then $\size{v}\le\size{\restr{\Sigma}{\Gamma}}+k$, where $k$ is a constant.
\end{enumerate}

\label{lem:stmt-invariant}
Given a statement $\mathsf{s}$ and a consistent pair $(\Gamma, \Sigma)$ such that $\typing{\Gamma}{\ell}{\mathsf{s}}{\Gamma'}$ and $\semantics{\Sigma}{\mathsf{s}}{\Sigma'}$ for some $\ell$, $\Gamma'$ and $\Sigma'$, then the following statements hold.
\begin{enumerate}
    \item If $\ell=\texttt{\#}\mathtt{t}$, then $\size{\Sigma'}\dot{-}\size{\Sigma}=O(\size{\restr{\Sigma}{\Gamma}}^d)$, where $d$ is a constant.
    \item If $\ell=\texttt{\#}\mathtt{f}$, then $\size{\Sigma'}\dot{-}\size{\Sigma}= O(\size{\Sigma}^{d^{k}})$, where $d$ and $k$ are constants.
\end{enumerate}

We start by recalling the definition of Turing machines.
A \textit{Turing machine} $M$ is a $6$-tuple $(Q, \{\texttt{0,1}\}, \Lambda, \delta, q_0, q_{halt})$, where
\begin{enumerate}
    \item $Q$ is a finite set of states,
    \item $\Lambda=\{\texttt{0,1, $\square$}\}$ where \texttt{$\square$} is the blank symbol,
    \item $q_0,q_{halt}\in Q$ are the start state and the halt state, respectively.
    \item $\delta:Q\times\Lambda\to Q\times\Lambda\times\{\texttt{L,R}\}$ is the transition function of $M$.
\end{enumerate}

The Turing machine $M$ has a single, one-way infinite tape and behaves in a standard manner.
Its configuration is represented by $uqw$, where $q$ is the current state, $uw\in\Lambda^{*}$ is the current tape content, and the head points at the first symbol of $w$.
When $M$ halts, the head will return to the leftmost position, and the content on the tape represents the computation result.

Given $M=(Q, \{\texttt{0,1}\}, \Lambda, \delta, q_0, q_{halt})$ whose running time is given by a polynomial $T(n)$.
There is a constant $d$ such that $T(n)\le dn^d$. We construct a program $\mathsf{p}$  with input variable \texttt{x} as follows:

\paragraph{Configuration.} We use an $\mathtt{int}$ variable \texttt{y} and the input variable \texttt{x} to present the contents of the tape in ternary representation, where the symbols \texttt{0}, \texttt{1}, and \texttt{$\square$} are represented by the digits 0, 1, and 2, respectively.
The value of \texttt{y} represents the contents to the left of the head, while the value of \texttt{x} represents the contents to the right of the head.
For convenience, the digits of \texttt{x} are in reverse order so that the least significant digit of \texttt{x} represents the content under the tape head.
Since the most significant digit cannot be $0$, we add an extra $2$ at the beginning of \texttt{x} and \texttt{y}.
Additionally, we declare an $\mathtt{int}$ variable \texttt{q} to simulate the state of $M$.
W.l.o.g., we assume that $Q=\{q_0,q_1,q_2,\cdots,q_{\size{Q}-1}\}$, where $q_1=q_{halt}$.

\paragraph{Input and Initialization.} Assume that the input on the tape are $w\in\{\texttt{0,1}\}^{*}$.
Let $w'=\texttt{2}\circ w^r$, where $w^r$ represents the reverse of $w$.
Interpret $w'$ as a ternary number and convert it to the corresponding decimal number $v$, which will serve as the input to $\mathsf{p}$.
We declare an \texttt{int} variable \texttt{y} and assign it the value $2$.
For example, if the input of $M$ is $w=$\texttt{10010}, then $w'=(201001)_3$ and $v=(514)_{10}$.

\paragraph{Timer.} We utilize the method presented in the proof of Lemma \ref{lemma:poly-con} to generate a value whose length grows to $d\size{v}^d$, and assign it to an iterable variable \texttt{cnt}.
Then we design a statement of the form \texttt{\textbf{for}(i<\textbf{size}(cnt))\{ $\dots$ \}} such that every Turing machine operation is simulated in an iteration of the loop.

\paragraph{Simulation.} Inside the loop body, we simulate $\delta$ by a sequence of conditional statements.
$M$ will only modify its state once in each step.
Therefore, we declare a boolean variable \texttt{flag} at the beginning of the loop body to indicate whether \texttt{q} has been updated.
For a given constant $m$, we introduce the syntax sugar \texttt{$m$*a}, which means \texttt{a+$\dots$+a} ($m$ occurrences of \texttt{a}).

\begin{enumerate}
    \item \textit{Read}. 
    For any transition $\delta(q_i, \alpha)$, where $i\ne1$, we use the following conditions to simulate the tape’s reading and state recognition.
    If they match, the statement inside \texttt{\{\}} simulates the instructions to be executed.
    $$\texttt{\textbf{if}(!flag \&\& q==$i$ \&\& x\%3==$\alpha$) \{$\dots$\}}.$$
    \item \textit{Write}. If $M$ needs to change the content to $\beta\in\Lambda$ and update the state to $q_j$, it can be done by executing
    $$\texttt{x=x-$\alpha$+$\beta'$; q=}j\texttt{; flag=\textbf{true};},$$
    where $\beta'$ is corresponding to $\beta$, i.e., if $\beta\in\{\texttt{0},\texttt{1}\}$, then $\beta'=\beta$; otherwise $\beta'=\texttt{2}$.
    Set \texttt{flag} to $\texttt{\#}\mathtt{t}$ to skip the remaining conditional statements.
    \item \textit{Leftward Movement}. If the head of $M$ needs to move left, the last digit of \texttt{y} is appended to the end of \texttt{x}.
    However, it is important to note that if the tape head is already at the leftmost position, no movement is performed. This process can be simulated as follows:
    $$\texttt{\textbf{if}(y>2) \{x=3*x+y\%3; y=y/3;\} \textbf{else} \{\}}$$
    In base three, the value of \texttt{y} always begins with $2$, representing the leftmost end of the tape (\texttt{$\square$}).
    \item \textit{Rightward Movement}. The rightward movement is simulated by appending the last digit of \texttt{x} to the end of \texttt{y}.
    If the head is in the rightmost position, it can still move right.
    In this case, the head will point to a blank symbol \texttt{$\square$}, so we should append digit \texttt{2} to the end of \texttt{y}.
    $$\texttt{y=3*y+x\%3; x=x/3; \textbf{if}(x<=2) \{x=3*x+2\} \textbf{else} \{\}}$$
    \item \textit{Halt and Output.} 
    We do not add any statements for $q_1$. 
    Once the program enters this state, it performs no operations until the loop terminates.
    Add \texttt{\textbf{return} x;} at the end of $\mathsf{p}$ to return the encoded output.
\end{enumerate}
For example, assuming $\delta(q_0,\texttt{0})=(q_1,\texttt{1},\mathtt{L})$ and $\delta(q_0,\texttt{1})=(q_3,\texttt{0},\mathtt{R})$, the corresponding simulation statements are shown in Figure \ref{fig:simulation}.
Since $\delta$ is defined on $Q\times\Lambda$, the number of conditional statements is at most $3\size{Q}$. 
Hence, the entire simulation process can be constructed in polynomial time.
