We say that a sequence of statements $\widetilde{\mathsf{s}}$ is simple if it consists of two parts: i) some declaration statements, and ii) a loop \texttt{\textbf{for}(i<\textbf{size}(y)) $\mathsf{s}'$}, where $\mathsf{s}'$ does not contain any loops or function calls.
We now transform the statements first.

\begin{claim}
    Let $\widetilde{\mathsf{s}}$ be a sequence of statements that does not contain any function calls, and \texttt{y} be a fresh variable
    There exists a bound $t_0(n)=n^{\size{\widetilde{\mathsf{s}}}^{O(\size{\widetilde{\mathsf{s}}})}}$ and a $O(\mathrm{poly}(\size{\widetilde{\mathsf{s}}}))$-size simple statement $\widetilde{\mathsf{s}}_0$ such that
    \begin{enumerate}
        \item the loop bound in $\widetilde{\mathsf{s}}_0$ is \texttt{\textbf{size}(y)}, and
        \item for any store $\Sigma$ such that $\semantics{\Sigma}{\widetilde{\mathsf{s}}}{\Sigma'}$ for some $\Sigma'$, and $|t|\ge t_0(\size{\Sigma})$, one has that $\semantics{\Sigma[\texttt{y}\mapsto t]}{\widetilde{\mathsf{s}}_0}{\Sigma'[\texttt{y}\mapsto t]}$.
    \end{enumerate}
    The notation $\size{\widetilde{\mathsf{s}}}:=\sum_{i=1}^m\size{\mathsf{s}_m}$, i.e., the sum of the bit-size of all statement in $\widetilde{\mathsf{s}}$.
\end{claim}

\begin{proof}
    Assume that $\widetilde{\mathsf{s}}=(\mathsf{s}_1,\dots,\mathsf{s}_m)$.
    We prove by induction on $m\ge 1$.
    If $m=1$, we prove by induction on the structure of statements.
    \begin{enumerate}
        \item Case \texttt{x=$\mathsf{e}$;}.
        Let $\widetilde{\mathsf{s}}_0:=\texttt{\textbf{for}(i<\textbf{size}(y)) \textbf{if}(i<1) x=$\mathsf{e}$; \textbf{else} \textbf{break};} $ and $t_0:=1$.
        Since $\mathsf{e}$ does not invoke any function calls, $\widetilde{\mathsf{s}}_0$ and $t_0$ satisfy all the conditions.
        \item Case $\texttt{\textbf{for}(j<\textbf{size}(z)) $\mathsf{s}'$}$.
        Applying the induction hypothesis, we can obtain $\widetilde{\mathsf{s}}_0'$ and $t_0'$.
        Assume that \begin{equation}
        \widetilde{\mathsf{s}}_{0}'\equiv \widetilde{\mathsf{s}}_{1}\texttt{ \textbf{for}(i<\textbf{size}(y)) }\mathsf{s}_{2},
    \end{equation}
    where $\widetilde{\mathsf{s}}_{1}$ corresponds to the declaration stage.  
    We can always rename variables in a way that \texttt{i} and \texttt{j} are two fresh variables.
    Let $\widetilde{\mathsf{s}}_0$ be the following statements.
\begin{lstlisting}
    `$\widetilde{\mathsf{s}}_1$`
    int i, j;
    for(k<size(y)) {
        if(j<size(z){
            `$\mathsf{s}_2$`
            i+=1;
            if(i>=size(y)/size(z)) {i=0; j+=1;}
        } else break;
    }
\end{lstlisting}
        According to Lemma~\ref{lem:stmt-invariant}, $\widetilde{\mathsf{s}}$ can only produce value bounded by a polynomial $p=O(n^{\size{\widetilde{\mathsf{s}}}^{\size{\widetilde{\mathsf{s}}}}})$.
        Let $t_0(n):=p(n)t'_0(p(n))$ and we are done.
        \item Other cases are trivial.
    \end{enumerate}

    If $\widetilde{\mathsf{s}}=(\widetilde{\mathsf{s}}_{\le m},\mathsf{s}_{m+1})$, then we first apply the induction hypothesis to obtain the corresponding simple statements and functions $\widetilde{\mathsf{s}}_{\le m, 0}$, $t_{\le m}$, $\widetilde{s}_{m+1,0}$ and $t_{m+1}$.
    Assume that
    \begin{equation}
        \widetilde{\mathsf{s}}_{\le m, 0}\equiv\widetilde{\mathsf{s}}_{\le m, 1}\texttt{ \textbf{for}(i<\textbf{size}(y)) }\mathsf{s}_{\le m, 2},
    \end{equation}
    \begin{equation}
        \widetilde{\mathsf{s}}_{m+1, 0}\equiv\widetilde{\mathsf{s}}_{m+1, 1}\texttt{ \textbf{for}(i<\textbf{size}(y)) }\mathsf{s}_{m+1, 2},
    \end{equation}
    where $\widetilde{\mathsf{s}}_{\cdot,1}$ corresponds to the declaration stage.
    Let $\widetilde{\mathsf{s}}_0$ be the following sequence.
    \begin{equation}
        \widetilde{\mathsf{s}}_{\le m, 1}\texttt{; }\widetilde{\mathsf{s}}_{m+1, 1}\texttt{ \textbf{for}(i<\textbf{size}(y)) \textbf{if}(i<\textbf{size}(y)/2) $\mathsf{s}_{\le m,2}$ \textbf{else} $\mathsf{s}_{m+1,2}$}.
    \end{equation}
    According to Lemma~\ref{lem:stmt-invariant}, $\widetilde{\mathsf{s}}_{\le m}$ can only produce value bounded by a polynomial $p=O(n^{\size{\widetilde{\mathsf{s}}_{\le m}}^{\size{\widetilde{\mathsf{s}}_{\le m}}}})$.
    Let $t_0:=2\max(t_{\le m}, t_{m+1} \circ \mathsf{p})$.
    It is easy to see that $\widetilde{s}_0$ and $t_0$ satisfy the three conditions.
    \qed
\end{proof}

